class Solution {
public:
    int maxSubarrayValue(std::vector<int>& nums, int k) {
        int n = nums.size();
        int ans = 0;
        for (int l = 0; l < n; ++l) {
            int cur_max = nums[l], cur_min = nums[l];
            for (int r = l; r < n; ++r) {
                cur_max = std::max(cur_max, nums[r]);
                cur_min = std::min(cur_min, nums[r]);
                if (r - l + 1 >= k) {
                    ans = std::max(ans, cur_max - cur_min);
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int maxSubarrayValue(int[] nums, int k) {
        int n = nums.length;
        int ans = 0;
        for (int l = 0; l < n; l++) {
            int curMax = nums[l], curMin = nums[l];
            for (int r = l; r < n; r++) {
                curMax = Math.max(curMax, nums[r]);
                curMin = Math.min(curMin, nums[r]);
                if (r - l + 1 >= k) {
                    ans = Math.max(ans, curMax - curMin);
                }
            }
        }
        return ans;
    }
}

var maxSubarrayValue = function(nums, k) {
    const n = nums.length;
    let ans = 0;
    for (let l = 0; l < n; l++) {
        let curMax = nums[l], curMin = nums[l];
        for (let r = l; r < n; r++) {
            if (nums[r] > curMax) curMax = nums[r];
            if (nums[r] < curMin) curMin = nums[r];
            if (r - l + 1 >= k) {
                const diff = curMax - curMin;
                if (diff > ans) ans = diff;
            }
        }
    }
    return ans;
};
